 IF include_notes AND replace(replace(d.notes,E'
',E'
'),E'',E'
') IS DISTINCT FROM s->'presentation'->>'reviewedNotes' THEN RETURN false; END IF;
 IF d.subtotal_price*100 IS DISTINCT FROM (f->>'subtotalPriceMinor')::numeric OR d.discount_amount*100 IS DISTINCT FROM (f->>'discountMinor')::numeric OR d.final_total_price*100 IS DISTINCT FROM (f->>'finalPriceMinor')::numeric OR d.subtotal_cost*100 IS DISTINCT FROM (f->>'estimatedCostMinor')::numeric OR to_jsonb(d.discount_applied) IS DISTINCT FROM f->'discountApplied' THEN RETURN false; END IF;
 IF d.scope_draft_id::text IS DISTINCT FROM s->'scopeReference'->>'scopeDraftId' THEN RETURN false; END IF;
 IF public.internal_approval_trim_v1(replace(replace(d.finish_level,E'
',E'
'),E'',E'
')) IS DISTINCT FROM pc->>'finishLevel' OR public.internal_approval_trim_v1(replace(replace(d.region,E'
',E'
'),E'',E'
')) IS DISTINCT FROM pc->>'region' OR public.internal_approval_trim_v1(replace(replace(d.zone,E'
',E'
'),E'',E'
')) IS DISTINCT FROM pc->>'zone' OR public.internal_approval_trim_v1(replace(replace(d.trade,E'
