CREATE OR REPLACE FUNCTION public.a1_export_exact_amount_minor_v1(quantity text, rate_two_decimal text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  q_scale integer; q_numerator numeric; r_cents numeric; numerator numeric; denominator numeric; quotient numeric; remainder numeric;
BEGIN
  q_scale := coalesce(length(split_part(quantity, '.', 2)), 0);
  q_numerator := replace(quantity, '.', '')::numeric;
  r_cents := replace(rate_two_decimal, '.', '')::numeric;
  numerator := q_numerator * r_cents;
  denominator := 10 ^ q_scale;
  quotient := trunc(numerator / denominator);
  remainder := numerator - quotient * denominator;
  IF remainder = 0 THEN RETURN quotient; END IF;
  IF 2 * remainder >= denominator THEN RETURN quotient + 1; END IF;
  RETURN quotient;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'A1_EXPORT_AMOUNT_INVALID' USING ERRCODE = '23514';
END $function$

CREATE OR REPLACE FUNCTION public.a1_export_exact_two_decimal_v1(snapshot_value text, candidate text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE whole text; fraction text;
BEGIN
  IF snapshot_value IS NULL THEN RETURN false; END IF;
  whole := split_part(snapshot_value, '.', 1);
  fraction := split_part(snapshot_value, '.', 2);
  IF length(fraction) > 2 THEN RETURN false; END IF;
  RETURN (whole || '.' || rpad(fraction, 2, '0')) = candidate;
END $function$

CREATE OR REPLACE FUNCTION public.a1_export_issue_order_valid_v1(issues jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  entry jsonb; seen jsonb := '[]'::jsonb;
  prev_rank smallint; prev_ordinal integer; prev_field integer;
  cur_rank smallint; cur_ordinal integer; cur_field integer;
  fields text[] := ARRAY['identity','approval','source','version','currency','lines','quantity','unit','unitCost',
    'unitPrice','lineCost','linePrice','costType','taxable','costCode','discount','format','bytes','renderer'];
  key jsonb; first_item boolean := true;
BEGIN
  FOR entry IN SELECT * FROM jsonb_array_elements(issues) LOOP
    key := jsonb_build_array(entry->'code', entry->'lineKey', entry->'field');
    IF seen @> jsonb_build_array(key) THEN RETURN false; END IF;
    seen := seen || jsonb_build_array(key);
    cur_rank := public.a1_export_issue_class_rank_v1(entry->>'code');
    IF cur_rank IS NULL THEN RETURN false; END IF;
    cur_ordinal := CASE WHEN entry->'lineKey' = 'null'::jsonb THEN -1 ELSE substring(entry->>'lineKey' FROM 6)::integer END;
    cur_field := CASE WHEN entry->'field' = 'null'::jsonb THEN -1 ELSE array_position(fields, entry->>'field') - 1 END;
    IF NOT first_item THEN
      IF cur_rank < prev_rank THEN RETURN false; END IF;
      IF cur_rank = prev_rank THEN
        IF cur_ordinal < prev_ordinal THEN RETURN false; END IF;
        IF cur_ordinal = prev_ordinal AND cur_field < prev_field THEN RETURN false; END IF;
      END IF;
    END IF;
    prev_rank := cur_rank; prev_ordinal := cur_ordinal; prev_field := cur_field; first_item := false;
  END LOOP;
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.historical_estimate_check_import_set()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  import_key uuid;
  expected_count integer;
  actual_count bigint;
  source_currency text;
  selected_total numeric;
  selected_cost numeric;
  reconciliation_status text;
BEGIN
  IF TG_TABLE_NAME = 'historical_estimate_imports' THEN
    import_key := NEW.id;
  ELSE
    import_key := NEW.import_id;
  END IF;
  SELECT i.expected_line_count, s.currency_code, i.declared_selected_total_minor,
    i.declared_selected_estimated_cost_minor, i.reconciliation_state
  INTO expected_count, source_currency, selected_total, selected_cost, reconciliation_status
  FROM public.historical_estimate_imports i
  JOIN public.historical_estimate_sources s ON s.tenant_id = i.tenant_id AND s.id = i.source_id
  WHERE i.tenant_id = NEW.tenant_id AND i.id = import_key;
  SELECT count(*) INTO actual_count
  FROM public.historical_estimate_import_lines
  WHERE tenant_id = NEW.tenant_id AND import_id = import_key;
  IF expected_count IS NULL OR actual_count IS DISTINCT FROM expected_count::bigint THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'hei_complete_line_set',
      MESSAGE = 'Historical selection requires its complete declared line set';
  END IF;
  IF source_currency IS NULL AND (selected_total IS NOT NULL OR selected_cost IS NOT NULL
      OR reconciliation_status IS DISTINCT FROM 'unresolved') THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'hei_unknown_currency',
      MESSAGE = 'Historical selection money requires an explicit supported source currency';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.historical_estimate_check_source_set()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  source_key uuid;
  expected_count integer;
  actual_count bigint;
  source_currency text;
BEGIN
  IF TG_TABLE_NAME = 'historical_estimate_sources' THEN
    source_key := NEW.id;
  ELSE
    source_key := NEW.source_id;
  END IF;
  SELECT expected_line_count, currency_code INTO expected_count, source_currency
  FROM public.historical_estimate_sources
  WHERE tenant_id = NEW.tenant_id AND id = source_key;
  SELECT count(*) INTO actual_count
  FROM public.historical_estimate_source_lines
  WHERE tenant_id = NEW.tenant_id AND source_id = source_key;
  IF expected_count IS NULL OR actual_count IS DISTINCT FROM expected_count::bigint THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'hes_complete_line_set',
      MESSAGE = 'Historical source requires its complete declared line set';
  END IF;
  IF source_currency IS NULL AND EXISTS (
    SELECT 1 FROM public.historical_estimate_source_lines
    WHERE tenant_id = NEW.tenant_id AND source_id = source_key
      AND (unit_price IS NOT NULL OR unit_estimated_cost IS NOT NULL
        OR line_price_minor IS NOT NULL OR line_estimated_cost_minor IS NOT NULL)
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'hesl_unknown_currency',
      MESSAGE = 'Historical money requires an explicit supported source currency';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.historical_estimate_valid_reconciliation(report jsonb, stored_state text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  finding jsonb;
  money_key text;
BEGIN
  IF jsonb_typeof(report) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
  IF NOT (report ?& ARRAY['version','state','sumPriceMinor','sumCostMinor','findings'])
    OR report - ARRAY['version','state','sumPriceMinor','sumCostMinor','findings'] <> '{}'::jsonb
    OR report->>'version' IS DISTINCT FROM 'historical-reconciliation-v1'
    OR report->>'state' IS DISTINCT FROM stored_state
    OR stored_state NOT IN ('unresolved','matched','mismatch')
  THEN RETURN false; END IF;
  FOREACH money_key IN ARRAY ARRAY['sumPriceMinor','sumCostMinor'] LOOP
    IF report->money_key <> 'null'::jsonb AND
      (jsonb_typeof(report->money_key) IS DISTINCT FROM 'string'
       OR (report->>money_key) !~ '^(0|[1-9][0-9]{0,19})$')
    THEN RETURN false; END IF;
  END LOOP;
  IF jsonb_typeof(report->'findings') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
  IF jsonb_array_length(report->'findings') > 4002 THEN RETURN false; END IF;
  FOR finding IN SELECT value FROM jsonb_array_elements(report->'findings') LOOP
    IF jsonb_typeof(finding) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
    IF NOT (finding ?& ARRAY['code','field'])
      OR finding - ARRAY['code','field','sourceLineKey','expectedMinor','actualMinor'] <> '{}'::jsonb
      OR jsonb_typeof(finding->'code') IS DISTINCT FROM 'string'
      OR finding->>'code' NOT IN ('unknown_currency','missing_line_price','missing_line_cost',
        'missing_declared_total','missing_declared_cost','price_total_mismatch','cost_total_mismatch',
        'price_extension_mismatch','cost_extension_mismatch','fractional_minor_extension','incomplete_extension')
      OR jsonb_typeof(finding->'field') IS DISTINCT FROM 'string'
      OR finding->>'field' NOT IN ('currency','price','cost')
    THEN RETURN false; END IF;
    IF finding ? 'sourceLineKey' AND (jsonb_typeof(finding->'sourceLineKey') IS DISTINCT FROM 'string'
      OR length(finding->>'sourceLineKey') NOT BETWEEN 1 AND 128)
    THEN RETURN false; END IF;
    IF finding ? 'expectedMinor' AND (jsonb_typeof(finding->'expectedMinor') IS DISTINCT FROM 'string'
      OR (finding->>'expectedMinor') !~ '^(0|[1-9][0-9]{0,29})$')
    THEN RETURN false; END IF;
    IF finding ? 'actualMinor' AND (jsonb_typeof(finding->'actualMinor') IS DISTINCT FROM 'string'
      OR (finding->>'actualMinor') !~ '^(0|[1-9][0-9]{0,19})$')
    THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.internal_approval_check_final_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE target uuid;d public.estimate_drafts;s public.estimate_internal_approval_snapshots;a public.estimate_internal_approvals;r public.estimate_internal_approval_revocations;child public.estimate_drafts;parent public.estimate_drafts;initial_evidence boolean:=TG_TABLE_NAME IN ('estimate_internal_approval_snapshots','estimate_internal_approvals');
BEGIN
 IF TG_TABLE_NAME='estimate_drafts' THEN target:=NEW.id;ELSE target:=NEW.estimate_draft_id;END IF;
 SELECT * INTO d FROM public.estimate_drafts WHERE id=target FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'A1_DRAFT_MISSING' USING ERRCODE='23514';END IF;
 SELECT * INTO s FROM public.estimate_internal_approval_snapshots WHERE estimate_draft_id=target;
 SELECT * INTO a FROM public.estimate_internal_approvals WHERE estimate_draft_id=target;
 SELECT * INTO r FROM public.estimate_internal_approval_revocations WHERE estimate_draft_id=target;
 IF s.id IS NULL AND a.id IS NULL AND r.id IS NULL THEN
  IF d.status IN ('internally_approved','internal_approval_revoked') THEN RAISE EXCEPTION 'A1_DECISION_PAIR_MISSING' USING ERRCODE='23514';END IF;
 ELSE
  IF s.id IS NULL OR a.id IS NULL OR a.snapshot_id<>s.id OR a.approved_by<>s.captured_by OR a.approved_at<>s.created_at OR d.version<>s.draft_version OR d.approved_by IS DISTINCT FROM a.approved_by OR d.approved_at IS DISTINCT FROM a.approved_at OR d.locked_at IS DISTINCT FROM a.approved_at OR (r.id IS NULL AND d.status<>'internally_approved') OR (r.id IS NOT NULL AND (d.status<>'internal_approval_revoked' OR r.revoked_at<a.approved_at)) THEN RAISE EXCEPTION 'A1_DECISION_STATE_MISMATCH' USING ERRCODE='23514';END IF;
  IF public.internal_approval_draft_matches_v1(d,s.snapshot_payload,initial_evidence) IS NOT TRUE THEN RAISE EXCEPTION 'A1_DRAFT_SNAPSHOT_MISMATCH' USING ERRCODE='23514';END IF;
  PERFORM public.internal_approval_check_lineage_v1(d.id);
 END IF;
 IF d.a1_version_request_id IS NOT NULL THEN
  SELECT * INTO parent FROM public.estimate_drafts WHERE id=d.supersedes_id FOR KEY SHARE;
  IF NOT FOUND OR parent.tenant_id IS DISTINCT FROM d.tenant_id OR parent.project_id IS DISTINCT FROM d.project_id OR parent.client_id IS DISTINCT FROM d.client_id OR parent.superseded_by IS DISTINCT FROM d.id THEN RAISE EXCEPTION 'A1_VERSION_CONTEXT_MISMATCH' USING ERRCODE='23514';END IF;
  PERFORM public.internal_approval_check_lineage_v1(d.id);
 END IF;
 SELECT * INTO child FROM public.estimate_drafts WHERE supersedes_id=d.id AND a1_version_request_id IS NOT NULL;
 IF FOUND AND (child.tenant_id IS DISTINCT FROM d.tenant_id OR child.project_id IS DISTINCT FROM d.project_id OR child.client_id IS DISTINCT FROM d.client_id OR d.superseded_by IS DISTINCT FROM child.id) THEN RAISE EXCEPTION 'A1_VERSION_CONTEXT_MISMATCH' USING ERRCODE='23514';END IF;
 IF s.id IS NOT NULL AND d.superseded_by IS NOT NULL AND (child.id IS NULL OR child.id<>d.superseded_by) THEN RAISE EXCEPTION 'A1_VERSION_SUCCESSOR_MISSING' USING ERRCODE='23514';END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.internal_approval_check_lineage_v1(root_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE root_d public.estimate_drafts;d public.estimate_drafts;stack jsonb;entry jsonb;path jsonb;seen uuid[]:='{}'::uuid[];current_id uuid;parent_id uuid;n integer:=0;
BEGIN
 SELECT * INTO root_d FROM public.estimate_drafts WHERE id=root_id;
 IF NOT FOUND OR root_d.tenant_id IS NULL OR root_d.client_id IS NULL THEN RAISE EXCEPTION 'A1_LINEAGE_CONTEXT_INVALID' USING ERRCODE='23514'; END IF;
 stack:=jsonb_build_array(jsonb_build_object('id',root_id,'path','[]'::jsonb));
 WHILE jsonb_array_length(stack)>0 LOOP
  entry:=stack->0;stack:=stack-0;current_id:=(entry->>'id')::uuid;path:=entry->'path';
  IF path @> jsonb_build_array(current_id::text) THEN RAISE EXCEPTION 'A1_LINEAGE_CYCLE' USING ERRCODE='23514';END IF;
  IF current_id=ANY(seen) THEN CONTINUE;END IF;
  n:=n+1;IF n>1000 THEN RAISE EXCEPTION 'A1_LINEAGE_LIMIT' USING ERRCODE='23514';END IF;
  SELECT * INTO d FROM public.estimate_drafts WHERE id=current_id FOR KEY SHARE;
  IF NOT FOUND OR d.tenant_id IS DISTINCT FROM root_d.tenant_id OR d.project_id IS DISTINCT FROM root_d.project_id OR d.client_id IS DISTINCT FROM root_d.client_id THEN RAISE EXCEPTION 'A1_LINEAGE_CONTEXT_INVALID' USING ERRCODE='23514';END IF;
  IF d.source IS NULL OR d.source NOT IN ('assembly_calculator','scope_draft','version','change_order') OR EXISTS(SELECT 1 FROM public.historical_estimate_imports h WHERE h.estimate_draft_id=d.id) THEN RAISE EXCEPTION 'A1_LINEAGE_SOURCE_INVALID' USING ERRCODE='23514';END IF;
  IF d.source='version' AND d.supersedes_id IS NULL OR d.source='change_order' AND d.change_order_of IS NULL THEN RAISE EXCEPTION 'A1_LINEAGE_PARENT_MISSING' USING ERRCODE='23514';END IF;
  seen:=array_append(seen,current_id);path:=path||jsonb_build_array(current_id::text);
  FOR parent_id IN SELECT DISTINCT p FROM unnest(ARRAY[d.supersedes_id,d.change_order_of]) AS p WHERE p IS NOT NULL ORDER BY p LOOP
   stack:=jsonb_build_array(jsonb_build_object('id',parent_id,'path',path))||stack;
  END LOOP;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.internal_approval_draft_matches_v1(d public.estimate_drafts, s jsonb, include_notes boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE f jsonb:=s->'financials';o jsonb:=s->'origin';pc jsonb:=s->'commercialContext'->'pricingContext';p jsonb:=s->'commercialContext'->'policyContext';raw jsonb;item jsonb;i integer;candidate text;resolved text;raw_risk text;raw_channel text;basis text;
BEGIN
 IF d.source IS DISTINCT FROM o->>'source' OR date_trunc('milliseconds',d.created_at) IS DISTINCT FROM (o->>'sourceCreatedAt')::timestamptz OR public.internal_approval_trim_v1(replace(replace(d.pricing_schema_version,E'
',E'
'),E'',E'
')) IS DISTINCT FROM o->>'pricingSchemaVersion' OR d.estimate_id::text IS DISTINCT FROM o->>'estimateId' OR d.intake_form_id::text IS DISTINCT FROM o->>'intakeFormId' OR d.bundle_id::text IS DISTINCT FROM o->>'bundleId' OR d.supersedes_id::text IS DISTINCT FROM o->>'supersedesId' OR d.change_order_of::text IS DISTINCT FROM o->>'changeOrderOf' THEN RETURN false; END IF;
 IF d.bundle_name IS NOT NULL AND public.internal_approval_trim_v1(replace(replace(d.bundle_name,E'
',E'
